export function calculateCurrentCapitalScenario(input,operating){
 const scenario=copy(input);
 if(!scenario?.ticker)throw Error('A company-specific capital scenario is required.');
 if(!scenario.optionPricing)return {...calculateDatedCapitalScenario(scenario,operating),ticker:scenario.ticker};
 if(scenario.ticker!=='AAOI'||scenario.optionPricing.model!=='aaoi-european-joint-v1')throw Error('Unsupported option-claim scenario.');
 if(scenario.optionPricing.asOf!==scenario.asOf)throw Error('Option and capital valuation dates must match.');
 const computed=['aaoi-note','aaoi-warrant'];
 if(!Array.isArray(scenario.baseline?.claims)||computed.some(id=>scenario.baseline.claims.filter(c=>c.id===id).length!==1))throw Error('Complete note and warrant claim definitions are required.');
 if(scenario.events?.some(e=>computed.includes(e.instrumentId)||e.removeClaimIds?.some(id=>computed.includes(id))))throw Error('Cannot combine the outstanding-option model with conversion of the same claims.');
 const before=copy(scenario);before.baseline.claims=before.baseline.claims.filter(c=>!computed.includes(c.id));
 const pool=calculateDatedCapitalScenario(before,operating);
 const priced=priceAaoiOptionClaims({...scenario.optionPricing,poolBeforeNoteAndWarrants:pool.equity,commonShares:pool.allocationShares});
 if(!priced.valid)throw Error(priced.errors?.join(' ')||'Option pricing inputs are incomplete.');
 scenario.baseline.claims.find(c=>c.id==='aaoi-note').amount=priced.noteTotal;
 scenario.baseline.claims.find(c=>c.id==='aaoi-warrant').amount=priced.warrantValue;
 const result=calculateDatedCapitalScenario(scenario,operating);
 return {...result,ticker:'AAOI',allocationLabel:'Conditional option-inclusive estimate',classification:'Explicit current-date analyst approximation; dated estimates and simplified European claim pricing, not exact fair value.',claimValuationMethod:'joint-dilution-adjusted-european-approximation',claimRepricedPerTrial:true,optionPricingResult:priced,warrantClaim:priced.warrantValue,warnings:[...AAOI_OPTION_LIMITATIONS,...result.warnings]};
}
